public void addMessage(final LogRecord lr) {
    // Create a new task to update the UI
    Runnable task = () -> {
        // Check if the log record is valid
        if (lr != null && getLogEntry(lr.getSequenceNumber()) == null) {
            // Get the next available sequence number
            long sequenceNumber = getNextSequenceNumber();

            // Create a new log entry
            LogEntry le = new LogEntry(sequenceNumber, lr.getLevel());
            le.setLocation(lr.getLocation());
            le.setMessage(lr.getMessage());
            le.setNDC(lr.getNDC());
            le.setThrownStackTrace(lr.getThrownStackTrace());
            le.setThrown(lr.getThrown());
            le.setMillis(lr.getMillis());

            // Add the log entry to the table model
            addLogEntry(le);
            fireTableRowsInserted(le.getIndex(), le.getIndex());
        }
    };

    // Post the task to the Swing thread
    SwingUtilities.invokeLater(task);
}

