/**
 * Apply the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
 * @param path the path to start from (usually a full file path)
 * @param relativePath the relative path to apply (relative to the full file path above)
 * @return the full file path that results from applying the relative path
 */
public static String applyRelativePath(String path, String relativePath) {
    int lastSlashIndex = path.lastIndexOf("/");
    if (lastSlashIndex == 0) {
        return "/" + relativePath;
    } else if (lastSlashIndex == -1) {
        return relativePath;
    } else {
        return path.substring(0, lastSlashIndex + 1) + relativePath;
    }
}

public static String applyRelativePath(String path, String relativePath) {
    String[] pathElements = path.split("/");
    String[] relativePathElements = relativePath.split("/");

    // Iterate over the relative path elements and append them to the end of the path
    for (String element : relativePathElements) {
        if (element.equals("..")) {
            // If the element is "..", remove the last path element
            if (pathElements.length > 1) {
                pathElements = Arrays.copyOfRange(pathElements, 0, pathElements.length - 1);
            }
        } else if (!element.isEmpty()) {
            // If the element is not ".." and is not empty, add it to the end of the path
            pathElements = Arrays.copyOf(pathElements, pathElements.length + 1);
            pathElements[pathElements.length - 1] = element;
        }
    }

    // Join the path elements into a single string
    return String.join("/", pathElements);
}

